{"command": "cd /tmp/w; timeout 280 python3 - <<'PY'
import subprocess, random, os
random.seed(1234)
VUL="/out-vul/gs_device_xpswrite_fuzzer"

def run(body):
    open("/tmp/w/fz.ps","w").write(body)
    try:
        r=subprocess.run([VUL,"/tmp/w/fz.ps"],capture_output=True,timeout=20)
        return r.returncode
    except subprocess.TimeoutExpired:
        return "TIMEOUT"

# template image generator with random params
def gen():
    w=random.choice([1,2,3,5,8,16,17,31,33,63,64,100,127,128,255,256])
    h=random.choice([1,2,3,5,8,16,17,31,33,63,64,100,127,128,255,256])
    bpc=random.choice([1,2,4,8,16])
    ncomp=random.choice([1,3,4])
    interp=random.choice(["true","false"])
    # data: sometimes truncated, sometimes extra
    datasize=w*h*ncomp*bpc//8
    mode=random.choice(["exact","trunc","extra","zero"])
    if mode=="exact": data="ab"*datasize
    elif mode=="trunc": data="ab"*max(0,datasize-random.randint(1,10))
    elif mode=="extra": data="ab"*(datasize+random.randint(1,100))
    else: data=""
    dec=" ".join(["0 1"]*ncomp)
    form=random.choice(["dict","op"])
    if form=="dict":
        ds=f"<< /ImageType 1 /Width {w} /Height {h} /BitsPerComponent {bpc} /Interpolate {interp} /Decode [{dec}] /ImageMatrix [{w} 0 0 -{h} 0 {h}] /DataSource currentfile >> image"
        return f"%!PS\n{ds}\n{data}\nshowpage\n"
    else:
        if ncomp==1:
            return f"%!PS\n{w} {h} {bpc} [{w} 0 0 -{h} 0 {h}] {{< {data[:80]} >}} image\nshowpage\n"
        else:
            return f"%!PS\n{w} {h} {bpc} [{w} 0 0 -{h} 0 {h}] {{ currentfile {w} string readhexstring pop }} false {ncomp} colorimage\n{data}\nshowpage\n"

crashes=[]
for i in range(400):
    body=gen()
    rc=run(body)
    if rc not in (0,"TIMEOUT",1):
        crashes.append((i,rc,body[:120]))
        print(f"[{i}] rc={rc} :: {body[:80]!r}")
        open(f"/tmp/w/crash_{i}.ps","w").write(body)
print("total crashes:", len(crashes))
for c in crashes[:10]: print(c[0], c[1])
PY"}

