#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <stdint.h>
// Simple ASan-like quarantine: poison freed blocks, delay reuse via a quarantine list.
static void* (*real_malloc)(size_t)=0;
static void (*real_free)(void*)=0;
static void* (*real_calloc)(size_t,size_t)=0;
static void* (*real_realloc)(void*,size_t)=0;
#define QMAX 4096
static void* quarantine[QMAX]; static size_t qsizes[QMAX]; static int qh=0,qt=0,qn=0;
static size_t alloc_size(void*p){ // from malloc_usable_size
    extern size_t malloc_usable_size(void*);
    return malloc_usable_size(p);
}
static void init(){ if(!real_malloc){real_malloc=dlsym(RTLD_NEXT,"malloc");real_free=dlsym(RTLD_NEXT,"free");real_calloc=dlsym(RTLD_NEXT,"calloc");real_realloc=dlsym(RTLD_NEXT,"realloc");} }
static void quarantine_push(void*p,size_t sz){
    // poison
    memset(p,0xFA,sz<4096?sz:4096);
    if(qn<QMAX){ quarantine[qt]=p; qsizes[qt]=sz; qt=(qt+1)%QMAX; qn++; }
    else { real_free(quarantine[qh]); qh=(qh+1)%QMAX; quarantine[qt]=p; qsizes[qt]=sz; qt=(qt+1)%QMAX; }
}
void free(void*p){ if(!p)return; init(); quarantine_push(p,alloc_size(p)); }
void* malloc(size_t n){ init(); return real_malloc(n); }
void* calloc(size_t a,size_t b){ init(); return real_calloc(a,b); }
void* realloc(void*p,size_t n){ init(); return real_realloc(p,n); }
EOF
