class F(gdb.Breakpoint):
    def __init__(self): super().__init__("free")
    def stop(self):
        a=int(gdb.parse_and_eval("$rdi"))
        if a==base: state.append(("FREE",a)); 
        return False
class M(gdb.Breakpoint):
    def __init__(self): super().__init__("malloc"); self.pending=False
    def stop(self):
        # capture return via a temporary finish is hard in breakpoint; skip
        return False
F(); 
# track reallocs too
class R(gdb.Breakpoint):
    def __init__(self): super().__init__("realloc")
    def stop(self):
        a=int(gdb.parse_and_eval("$rdi"))
        if a==base: state.append(("REALLOC_in",a))
        return False
R()
gdb.execute("continue")
# count consecutive frees without realloc
gaps=0; lastfree=False; doublecount=0
for op,a in state:
    if op=="FREE":
        if lastfree: doublecount+=1
        lastfree=True
    else:
        lastfree=False
gdb.write("free/realloc events on base: %d, consecutive-double-frees: %d\n"%(len(state),doublecount))
for op,a in state[:20]: gdb.write("  %s %#x\n"%(op,a))
gdb.execute("quit")
